import SkeletonService from '../../../../../src/services/SkeletonService';
import { getCollection } from '../../../../../src/lib/mongodb';
import { ObjectId } from 'mongodb';

/**
 * SaveEditCtrl - Laravel SaveEditCtrl.php equivalent
 * Saves updated records
 * Auto-generated by ModuleGenerator
 */
export default class SaveEditCtrl {
  /**
   * index method - Main handler
   * @param {Request} req 
   * @param {Response} res 
   * @returns {Promise<Response>}
   */
  async index(req, res) {
    try {
      console.log('🎯 SaveEditCtrl::index() called');

      const token = req.body.save_token;
      
      if (!token) {
        return res.status(400).json({
          status: false,
          title: 'Token Missing',
          message: 'No token was provided.'
        });
      }

      // Resolve token
      const reqSet = await SkeletonService.resolveToken(token);
      
      if (!reqSet || !reqSet.status || !reqSet.key) {
        return res.status(400).json({
          status: false,
          title: 'Invalid Token',
          message: 'The provided token is invalid.'
        });
      }

      // Get record ID from body (frontend sends it) or from token resolution
      const recordId = req.body.id || req.body.record_id || reqSet.id;
      
      if (!recordId) {
        return res.status(400).json({
          status: false,
          title: 'Invalid Data',
          message: 'Record ID is required for update.'
        });
      }

      // MongoDB uses _id as primary key, convert recordId to ObjectId if needed
      const idColumn = reqSet.act || '_id';
      let queryId = recordId;
      if (idColumn === '_id') {
        try {
          if (ObjectId.isValid(recordId)) {
            queryId = new ObjectId(recordId);
          }
        } catch (e) {
          // Keep original value if conversion fails
        }
      }

      let reloadTable = false;
      let reloadCard = false;
      let validated = {};
      let title = 'Success';
      let message = 'Record updated successfully.';

      // Handle different configuration keys
      switch (reqSet.key) {
        case 'central_email_config':
          // Validate required fields based on bv SaveEditCtrl.php
          const allowedRegions = [
            'North America',
            'South America',
            'APJ & APAC',
            'EMEA',
            'MENA',
            'DACH',
            'Oceania',
            'NORDICS',
          ];

          // Basic validation
          if (!req.body.first_name || !req.body.last_name) {
            return res.status(400).json({
              status: false,
              title: 'Validation Error',
              message: 'First name and last name are required.'
            });
          }

          if (req.body.region && !allowedRegions.includes(req.body.region)) {
            return res.status(400).json({
              status: false,
              title: 'Validation Error',
              message: 'Valid region is required.'
            });
          }

          // Prepare validated data (only update provided fields)
          validated = {
            updated_by: req.user?.user_id || null,
            updated_at: new Date()
          };

          // Add fields that are provided
          if (req.body.first_name !== undefined) validated.first_name = req.body.first_name.trim();
          if (req.body.last_name !== undefined) validated.last_name = req.body.last_name.trim();
          if (req.body.extension !== undefined) validated.extension = req.body.extension || null;
          if (req.body.phone_number !== undefined) validated.phone_number = req.body.phone_number || null;
          if (req.body.designation !== undefined) validated.designation = req.body.designation || null;
          if (req.body.postal_code !== undefined) validated.postal_code = req.body.postal_code || null;
          if (req.body.address !== undefined) validated.address = req.body.address || null;
          if (req.body.fax !== undefined) validated.fax = req.body.fax || null;
          if (req.body.unsubscribe !== undefined) validated.unsubscribe = req.body.unsubscribe;
          if (req.body.region !== undefined) validated.region = req.body.region.trim();
          if (req.body.status !== undefined) validated.status = req.body.status;
          if (req.body.daily_send_limit !== undefined) validated.daily_send_limit = parseInt(req.body.daily_send_limit) || 100;

          // Update in database
          // email_accounts collection is in pluto database
          const collectionSystem = reqSet.table === 'email_accounts' ? 'pluto' : (reqSet.system || 'central');
          const collection = await getCollection(reqSet.table, collectionSystem);
          const updateResult = await collection.updateOne(
            { [idColumn]: queryId },
            { $set: validated }
          );

          if (updateResult.matchedCount === 0) {
            return res.status(404).json({
              status: false,
              title: 'Not Found',
              message: 'Email account not found.'
            });
          }

          reloadTable = true;
          title = 'Email Account Updated';
          message = 'Email account updated successfully.';
          break;

        case 'central_emailsystem':
          // Default case for other emailsystem tokens
          break;

        default:
          return res.status(400).json({
            status: false,
            title: 'Invalid Configuration',
            message: 'The configuration key is not supported.'
          });
    }

    return res.status(200).json({
      status: true,
        reload_table: reloadTable,
        reload_card: reloadCard,
        token: reqSet.key,
        affected: recordId || '-',
        title: title,
        message: message
    });

  } catch (error) {
      console.error('❌ SaveEditCtrl error:', error);

      // Handle MongoDB duplicate key error (E11000)
      if (error.code === 11000 || error.codeName === 'DuplicateKey') {
      return res.status(400).json({
        status: false,
        message: 'A record with this key already exists'
      });
    }

    return res.status(500).json({
      status: false,
        title: 'Error',
        message: error.message || 'An error occurred while saving the data.'
    });
    }
  }
}
